/* ---- hero flow-field animation ---- */
;
(function () {
  "use strict";

  var canvas = document.getElementById("heroFlow");
  if (!canvas) return;
  var ctx = canvas.getContext("2d");
  var hero = canvas.parentElement;
  var reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;

  var GAP = 24;           // grid pitch (px)
  var BASE_A = 0.02;      // floor opacity for a lit cell
  var PEAK_A = 0.13;      // extra opacity at a wave crest — keep low = muted
  var THRESH = 0.30;      // below this wave value a cell stays dark
  var SPEED = 2.2;        // wave temporal frequency

  var w, h, dpr, palette = readPalette();
  var px = -9999, py = -9999, hasPointer = false;

  function readPalette() {
    var probe = document.createElement("span");
    probe.style.cssText = "position:absolute;opacity:0;pointer-events:none";
    hero.appendChild(probe);
    function col(v) { probe.style.color = v; return getComputedStyle(probe).color; }
    var p = { bg: col("var(--bg)"), accent: col("var(--brutal-accent)"), hot: col("var(--fg-bright)"), dim: col("var(--fg2)") };
    probe.remove();
    return p;
  }
  function withAlpha(c, a) { var m = c.match(/\d+(\.\d+)?/g); return "rgba(" + m[0] + "," + m[1] + "," + m[2] + "," + a + ")"; }

  function resize() {
    dpr = Math.min(window.devicePixelRatio || 1, 2);
    w = hero.clientWidth; h = hero.clientHeight;
    canvas.width = Math.round(w * dpr); canvas.height = Math.round(h * dpr);
    canvas.style.width = w + "px"; canvas.style.height = h + "px";
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }

  function draw(t) {
    ctx.fillStyle = palette.bg; ctx.fillRect(0, 0, w, h);
    // Roaming wave source so the pulse direction drifts over time.
    var sx = w * 0.5 + Math.cos(t * 0.6) * w * 0.32;
    var sy = h * 0.5 + Math.sin(t * 0.8) * h * 0.34;
    for (var y = GAP / 2; y < h; y += GAP) {
      for (var x = GAP / 2; x < w; x += GAP) {
        var dx = x - sx, dy = y - sy, d = Math.sqrt(dx * dx + dy * dy);
        var v = Math.sin(d * 0.045 - t * SPEED);
        if (hasPointer) {
          var qx = x - px, qy = y - py, qd = Math.sqrt(qx * qx + qy * qy);
          v += Math.sin(qd * 0.07 - t * 6) * Math.exp(-qd * qd / 40000);
        }
        var it = (v + 1) / 2;                       // 0..1
        if (it < THRESH) continue;
        var k = (it - THRESH) / (1 - THRESH);        // 0..1 above threshold
        var sz = 2 + k * (GAP * 0.42);
        // Mostly muted ink; only the very crest tints faint cyan.
        var col = k > 0.86 ? palette.accent : (k > 0.55 ? palette.hot : palette.dim);
        ctx.fillStyle = withAlpha(col, BASE_A + k * PEAK_A);
        ctx.fillRect(x - sz / 2, y - sz / 2, sz, sz);
      }
    }
  }

  function onMove(e) {
    var r = hero.getBoundingClientRect();
    var x = e.clientX - r.left, y = e.clientY - r.top;
    hasPointer = x >= 0 && x <= w && y >= 0 && y <= h;
    px = x; py = y;
  }

  var raf = 0;
  resize();

  if (reduce) { draw(0); window.addEventListener("resize", function () { resize(); draw(0); }); return; }

  function loop(now) { draw(now * 0.001); raf = requestAnimationFrame(loop); }
  window.addEventListener("pointermove", onMove, { passive: true });
  window.addEventListener("pointerleave", function () { hasPointer = false; });
  window.addEventListener("resize", resize);
  document.addEventListener("visibilitychange", function () {
    cancelAnimationFrame(raf);
    if (!document.hidden) raf = requestAnimationFrame(loop);
  });
  new MutationObserver(function () { palette = readPalette(); })
    .observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme"] });

  raf = requestAnimationFrame(loop);
})();

